graphql-intro-001.example:
```graphql
# A client asks for exactly these fields and nothing more.
query {
  user(id: "1") {
    name
    posts {
      title
    }
  }
}
```

graphql-intro-002.example:
```js
// Every GraphQL request hits the same URL; the body carries the query.
await fetch('https://api.example.com/graphql', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    query: `{ user(id: "1") { name email } }`,
  }),
});
```

graphql-intro-003.example:
```graphql
# One request replaces a /user call + a /user/:id/posts call,
# and returns only the three fields this screen renders.
query HomeScreen {
  user(id: "1") {
    name
    posts {
      title
    }
  }
}
```

graphql-intro-004.example:
```graphql
type User {
  id: ID!
  name: String!
  posts: [Post!]!
}

type Post {
  id: ID!
  title: String!
}

type Query {
  user(id: ID!): User
}
```

graphql-query-001.example:
```graphql
query {
  user(id: "1") {
    name          # scalar leaf — no braces
    address {     # object branch — needs a selection set
      city
      country
    }
  }
}
```

graphql-query-002.example:
```graphql
query {
  user(id: "1") {
    name
    profilePic(size: 100)   # argument on a nested field
  }
}
```

graphql-query-003.example:
```graphql
query {
  empireHero: hero(episode: EMPIRE) {
    name
  }
  jediHero: hero(episode: JEDI) {
    name
  }
}
```

graphql-query-004.example:
```graphql
query {
  empireHero: hero(episode: EMPIRE) {
    ...heroFields
  }
  jediHero: hero(episode: JEDI) {
    ...heroFields
  }
}

fragment heroFields on Character {
  name
  appearsIn
}
```

graphql-query-005.example:
```graphql
query HeroByEpisode($episode: Episode = JEDI, $withFriends: Boolean!) {
  hero(episode: $episode) {
    name
    friends @include(if: $withFriends) {
      name
    }
  }
}
```

graphql-query-006.example:
```graphql
query GetUser($id: ID!) {
  user(id: $id) {
    name
    email
  }
}
```

graphql-query-mcq-001.example:
```graphql
query Hero($episode: Episode, $withFriends: Boolean!, $skipName: Boolean!) {
  hero(episode: $episode) {
    name @skip(if: $skipName)
    friends @include(if: $withFriends) {
      name
    }
  }
}
```

graphql-query-mcq-002.example:
```graphql
query {
  empireHero: hero(episode: EMPIRE) { name }
  jediHero: hero(episode: JEDI) { name }
}
```

graphql-query-mcq-003.example:
```graphql
query {
  search(text: "an") {
    __typename
    ... on Human { name }
    ... on Droid { name }
    ... on Starship { name }
  }
}
```

graphql-query-mr-001.example:
```graphql
query {
  me: user(id: "1") {        # alias
    ...userCard              # fragment spread
    avatar(size: 64)         # nested-field argument
  }
}

fragment userCard on User {
  name
  email
}
```

graphql-mutation-001.example:
```graphql
mutation {
  createReview(episode: JEDI, review: { stars: 5, commentary: "Great!" }) {
    stars
    commentary
  }
}
```

graphql-mutation-002.example:
```graphql
input CreateUserInput {
  name: String!
  email: String!
  age: Int
}

type Mutation {
  createUser(input: CreateUserInput!): User!
}
```

graphql-mutation-003.example:
```graphql
type CreateUserPayload {
  user: User
  errors: [UserError!]!
}

type UserError {
  field: String
  message: String!
}

type Mutation {
  createUser(input: CreateUserInput!): CreateUserPayload!
}
```

graphql-mutation-mcq-001.example:
```graphql
mutation {
  first: createUser(input: { name: "A", email: "a@x.com" }) { id }
  second: createUser(input: { name: "B", email: "b@x.com" }) { id }
  # `first` fully completes before `second` begins.
}
```
